                for (uint i = 0; i < n; i++) if (!eliminated[i]) { winner = i; emit FinalizedEvent(); return; }
            }

            eliminated[minIdx] = true;
            remaining--;
            if (remaining == 1) {
                for (uint i = 0; i < n; i++) if (!eliminated[i]) { winner = i; emit FinalizedEvent(); return; }
